import{_ as a,o as s,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"定制版 ClassIsland（AgoraIn 集控客户端）","description":"基于 ClassIsland 的 AgoraIn 定制版：内置集控客户端，接收通知 / 播报 / 锁屏 / 电源控制 / 课表推送与呼叫提醒（GPL-3.0 开源）","frontmatter":{"title":"定制版 ClassIsland（AgoraIn 集控客户端）","description":"基于 ClassIsland 的 AgoraIn 定制版：内置集控客户端，接收通知 / 播报 / 锁屏 / 电源控制 / 课表推送与呼叫提醒（GPL-3.0 开源）"},"headers":[],"relativePath":"custom-classisland.md","filePath":"custom-classisland.md","lastUpdated":1792285702000}'),o={name:"custom-classisland.md"};function d(n,t,e,i,h,g){return s(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="定制版-classisland-agorain-集控客户端" tabindex="-1">定制版 ClassIsland（AgoraIn 集控客户端） <a class="header-anchor" href="#定制版-classisland-agorain-集控客户端" aria-label="Permalink to &quot;定制版 ClassIsland（AgoraIn 集控客户端）&quot;">​</a></h1><blockquote><p><strong>一句话</strong>：这是基于 <a href="https://github.com/ClassIsland/ClassIsland" target="_blank" rel="noreferrer">ClassIsland</a> 的 AgoraIn 定制分支， 在原有课表 / 提醒 / 界面能力之上，<strong>内置了 AgoraIn 集控客户端</strong> —— 教室一体机装上它， 就能接收教师端下发的通知、语音播报、锁屏、电源控制、课表推送与呼叫提醒。</p><p>许可：<strong>GPL-3.0 开源</strong>（ClassIsland 衍生作品，源码随包提供，详见<a href="/license.html">开源许可声明</a>）。</p></blockquote><h2 id="一、和-一体机插件-有什么区别" tabindex="-1">一、和&quot;一体机插件&quot;有什么区别？ <a class="header-anchor" href="#一、和-一体机插件-有什么区别" aria-label="Permalink to &quot;一、和&quot;一体机插件&quot;有什么区别？&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>一体机插件（<code>.cipx</code>）</th><th><strong>定制版 ClassIsland（本页）</strong></th></tr></thead><tbody><tr><td>形态</td><td>ClassIsland 的插件，装在你现有的 ClassIsland 里</td><td>一整个 ClassIsland 客户端（解压即用）</td></tr><tr><td>能力</td><td>呼叫接收（弹窗 + 朗读）、课表同步</td><td>呼叫接收 <strong>+ 完整集控指令</strong>：通知 / 播报 / 锁屏 / 解锁 / 网页 / 应用启停 / 课表推送 / 日志上传 / 设置下发 / 休眠 / 重启 / 关机</td></tr><tr><td>关于页</td><td>—</td><td>显示 <strong>AgoraIn 品牌信息与定制版本号</strong></td></tr><tr><td>适合</td><td>已经有一套 ClassIsland 在跑，只想加联动</td><td>教室一体机想一次装好、被平台统一管控</td></tr></tbody></table><p>两者可以共存：插件负责你原有 ClassIsland 的呼叫联动；定制版适合新装教室机。</p><h2 id="二、下载与安装" tabindex="-1">二、下载与安装 <a class="header-anchor" href="#二、下载与安装" aria-label="Permalink to &quot;二、下载与安装&quot;">​</a></h2><ol><li>打开<a href="/download.html">下载中心</a>，下载 <strong>定制版 ClassIsland（AgoraIn 集控客户端）</strong>；</li><li>解压到任意目录（如 <code>D:\\AgoraInClassIsland</code>）—— <strong>自包含打包，无需安装 .NET 运行时</strong>；</li><li>双击 <code>ClassIsland.Desktop.exe</code> 启动（首次启动按向导完成基础设置即可）。</li></ol><blockquote><p>系统要求：Windows 10 1809+（教室一体机 / 电子白板 / 普通 PC 均可）。</p></blockquote><h2 id="三、连接到-agorain-集控平台" tabindex="-1">三、连接到 AgoraIn 集控平台 <a class="header-anchor" href="#三、连接到-agorain-集控平台" aria-label="Permalink to &quot;三、连接到 AgoraIn 集控平台&quot;">​</a></h2><ol><li><p>打开客户端 → <strong>设置 → 集控 → 加入管理</strong>；</p></li><li><p>在「<strong>AgoraIn 集控平台（定制版）</strong>」一栏填写服务器地址：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://agorain.615mc.cn</span></span></code></pre></div><p>（连接密码：平台未启用连接密码时留空即可；如机构自行部署了服务端，填你自己的地址）</p></li><li><p>点「<strong>连接到 AgoraIn 集控平台</strong>」，看到「已登记」即接入成功；</p></li><li><p>回到教师端 → 教学模式 →「<strong>集控平台</strong>」，设备列表会出现这台教室机（名称形如 <code>ClassIsland-&lt;计算机名&gt;</code>）， 此后即可对其下发指令，指令历史里能看到<strong>执行回执</strong>。</p></li></ol><h2 id="四、支持的集控指令" tabindex="-1">四、支持的集控指令 <a class="header-anchor" href="#四、支持的集控指令" aria-label="Permalink to &quot;四、支持的集控指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>教室端行为</th></tr></thead><tbody><tr><td>通知弹窗 / 自定义消息</td><td>顶部提醒横幅显示文本</td></tr><tr><td>语音播报</td><td>横幅 + 中文语音朗读</td></tr><tr><td>锁定屏幕 / 解锁屏幕</td><td>锁屏（解锁需本机手动操作，Windows 不允许程序自动解锁）</td></tr><tr><td>打开网页 / 启动应用 / 结束应用</td><td>默认浏览器打开网址 / 启动指定程序 / 按进程名结束</td></tr><tr><td>推送课表档案 / 刷新课表</td><td>重新拉取平台下发的课表并刷新显示</td></tr><tr><td>上传日志</td><td>打包客户端日志到 <code>LogUploads\\*.zip</code>，回执里带上路径（排障用）</td></tr><tr><td>下发设置</td><td>记录并回执（具体键值映射按机构策略配置）</td></tr><tr><td>休眠 / 重启 / 关机</td><td>系统电源操作（<strong>首次上线前建议先在 1 台机器演练</strong>）</td></tr><tr><td>呼叫提醒（下课传唤 / 上课应急 / 待下课通知）</td><td>提醒横幅 + 语音朗读，应急类型置顶</td></tr></tbody></table><h2 id="五、关于页的品牌信息" tabindex="-1">五、关于页的品牌信息 <a class="header-anchor" href="#五、关于页的品牌信息" aria-label="Permalink to &quot;五、关于页的品牌信息&quot;">​</a></h2><p>定制版的「设置 → 关于」中新增了 <strong>AgoraIn 定制版</strong> 卡片：显示 AgoraIn 标志、定制版本号、 集控客户端说明与平台入口链接；同时保留上游 ClassIsland 的版本、开源许可与贡献者信息。</p><h2 id="六、源码与许可" tabindex="-1">六、源码与许可 <a class="header-anchor" href="#六、源码与许可" aria-label="Permalink to &quot;六、源码与许可&quot;">​</a></h2><ul><li>本定制版是 ClassIsland 的衍生作品，<strong>整体以 GPL-3.0 发布</strong>，源码随二进制提供；</li><li>与 AgoraIn 服务端（闭源商业软件）之间<strong>只通过 HTTP 协议对接</strong>，双方不链接彼此代码；</li><li>上游项目：<a href="https://github.com/ClassIsland/ClassIsland" target="_blank" rel="noreferrer">https://github.com/ClassIsland/ClassIsland</a>（同样为 GPL-3.0）；</li><li>完整说明（含服务端集控插件、第三方库许可、常见误解澄清）：<a href="/license.html">开源许可声明</a>。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：客户端显示&quot;已连接&quot;但收不到指令？</strong> 先确认教师端「集控平台」里这台设备是在线的；若客户端所在机器装了代理软件，请把平台地址加入直连（程序已按直连方式访问内网地址）。</p><p><strong>Q：能用上游官方版 ClassIsland 吗？</strong> 可以，但官方版没有集控指令通道；要接收通知/播报/锁屏/电源控制等，需要用本定制版（或等待后续插件化支持）。</p><p><strong>Q：解压后提示缺少运行库？</strong> 本包为自包含发布，正常情况下不需要任何运行时；若被安全软件拦截，请放行 <code>ClassIsland.Desktop.exe</code>。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/teaching.html">教学模式</a> · <a href="/license.html">开源许可声明</a> · <a href="/plugin.html">一体机联动</a></li></ul>',22)])])}const u=a(o,[["render",d]]);export{p as __pageData,u as default};
